// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";

/// @notice Arbitrum ArbSys precompile (0x64) — the L2 block clock (~0.1-0.25s).
interface IArbSys {
    function arbBlockNumber() external view returns (uint256);
    function arbBlockHash(uint256 arbBlockNum) external view returns (bytes32);
}

/// @notice The shared settings contract (CasinoHubV5): platform fee + treasury.
interface ICasinoHubV7 {
    function feeInfo() external view returns (address treasury, uint256 platformFeeBP);
    function roomFeeOf(address who) external view returns (uint256);
}

/**
 * @title CasinoGameBaseV7 — V6 + the 2026-10-28 pre-launch audit fixes:
 *  • An exit is paid on the pool NET of every open bet's reserved max payout (min of the requested value, that and the
 *    free liquidity): a pending win — a stand-able run's cash-out, an outcome readable before its reveal — is always
 *    inside the reserve, so no exit can leave before it is paid, and the last staker's exit can always be paid.
 *  • Payouts never revert: a transfer that fails (a frozen / blacklisted player) is booked as `owed` and pulled with
 *    claimOwed() — one frozen address can no longer lock a room.
 *  • Auto-settle always scans past live bets (a standing run no longer parks the cursor).
 *  • rtp ≥ 80 %; platform fee ≤ 1 % (the rtp caps assume it); the LP-fee setting is gone (config.feeBP is always 0).
 *
 * V6 notes — two audit changes (2026-10-24):
 *  • TWO-STEP EXIT. requestUnstake() fixes the value of the shares; claimUnstake() pays the LOWER of that value and the
 *    value after EXIT_DELAY L2 blocks (every bet open at the request is revealed or expired by then). An LP who reads a
 *    pending win and leaves still carries it; what the shares gained meanwhile stays with the other LPs.
 *  • donate(): anyone adds tokens to the pool without taking shares (fee income for every LP — the launchpad routes
 *    the games' share of trading fees here).
 *
 * Original V5 notes:
 * @notice Shared engine for every V5 casino room. Same security model as V4 (L2-clock
 *         commit-reveal, config snapshot per bet, full liability reservation, virtual-offset
 *         shares, fee-on-transfer guard) with the V5 economy changes:
 *
 *  • Staker fees accrue INTO the pool (share value) — no claim step, no reward accumulator.
 *    Each staker's cost basis is tracked so the UI shows net won/lost (stakerPosition).
 *  • Platform fee is read from CasinoHubV5 (default 1%, capped at 2% here as well) and is
 *    ACCRUED, not transferred per bet; flushPlatformFees() (permissionless) sends it to the
 *    hub's treasury. Creator fee (1%) accrues the same way (claimCreatorFees()).
 *  • No keeper and no manual forfeit needed: every commit / stake / unstake first closes
 *    rounds whose entropy window expired (settleCursor walks bets in id order), so reserved
 *    liquidity can never stay locked. settleExpired(n) does the same on demand. An expired
 *    round is never refunded (that would hand players a free option — the outcome is known
 *    ~0.5s after commit); the stake stays in the pool, as in V4.
 *  • Gas: packed config / pool / fee slots, packed bet structs in the games, transient
 *    reentrancy lock, custom errors, no per-bet token transfers except the player's own.
 *  • RTP belongs to the room owner (creator): up to rtpCap() (98% by default; games with a
 *    lower raw EV allow more), changeable any time via updateConfig — open bets keep the
 *    RTP they were placed with.
 */
abstract contract CasinoGameBaseV7 is ReentrancyGuardTransient {
    using SafeERC20 for IERC20;

    // ── Constants ────────────────────────────────────────────
    IArbSys internal constant ARB = IArbSys(address(0x64));
    uint256 public constant CREATOR_FEE_BP      = 100;  // 1% to the room creator
    uint256 public constant MAX_PLATFORM_FEE_BP = 100;  // hub can never charge more than 1% (the rtp caps assume it)
    uint256 public constant MAX_LP_FEE_BP       = 0;    // no LP-fee setting: stakers earn the rtp edge
    uint256 public constant MIN_RTP_BP          = 8000; // below this some fixed payouts (blackjack push) outgrow their reserve
    uint256 public constant REVEAL_DELAY        = 2;    // L2 blocks before reveal (~0.5s)
    uint256 public constant REVEAL_WINDOW       = 240;  // L2 blocks the entropy hash is usable (< 256)
    uint256 internal constant AUTO_STEPS        = 4;    // expired rounds closed per commit/stake
    uint256 internal constant UNSTAKE_STEPS     = 32;   // … per exit
    uint256 public constant EXIT_DELAY          = REVEAL_DELAY + REVEAL_WINDOW + 2;   // L2 blocks between request and claim
    uint256 internal constant BP                = 10000;
    uint256 internal constant VIRTUAL           = 1e6;  // share/asset virtual offset (inflation guard)
    uint256 internal constant MAX_AMOUNT        = 2**104; // keeps every packed field far from overflow

    // ── Errors ───────────────────────────────────────────────
    error NotOwner(); error NotCreator(); error IsPaused(); error BadConfig(); error ZeroAddress();
    error BelowMinBet(); error BetExceedsMax(); error WinExceedsMax(); error InsufficientLiquidity();
    error FeeOnTransfer(); error AmountTooLarge(); error ZeroAmount(); error TooSmall();
    error ExceedsStake(); error LockedByOpenBets(); error NoStake();
    error Wait(); error EntropyExpired(); error NotFound(); error AlreadySettled(); error TooEarly(); error BadInput();
    error ExitPending(); error NoExit(); error NoShares(); error RevealFee();

    // ── Config (one slot; getter keeps the V4 field order) ───
    struct Config { uint16 rtpBP; uint16 feeBP; uint16 maxWinBP; uint128 minBet; uint16 maxBetPoolRatio; }
    Config public config;

    // ── Identity ─────────────────────────────────────────────
    address public owner;
    bool    public paused;
    address public creator;
    address public immutable factory;
    ICasinoHubV7 public immutable hub;
    IERC20  public immutable token;
    string  public tokenLogoUrl;
    string  public betName;

    // ── Pool & fees (packed: the hot slots of every bet) ─────
    uint128 public poolBalance;          // tokens backing the room (LP capital + retained stakes + LP fees)
    uint128 public lockedLiability;      // sum of max payouts of all open bets
    uint128 public pendingPlatformFees;  // accrued, sent to the hub treasury by flushPlatformFees()
    uint128 public pendingCreatorFees;   // accrued, sent to the creator by claimCreatorFees()
    uint128 public totalVolume;
    uint128 public totalPayouts;
    uint128 public totalFeesCollected;   // LP fee retained in the pool (lifetime)
    uint64  public settleCursor;         // every bet id below this is closed
    uint64  public expiredCount;         // rounds closed by expiry (lifetime)
    uint64  internal scanCursor;         // where the walk past live bets resumes (see _autoSettle)
    uint128 internal platformFeesSent;
    uint128 internal creatorFeesSent;
    uint128 public totalOwed;            // payouts whose transfer failed, waiting for claimOwed() (not pool money)

    // ── Payouts that couldn't be sent (frozen / blacklisted receiver) ──
    mapping(address => uint256) public owed;

    // ── Reveal fees (ETH): every commit pays whoever reveals it — a keeper reveals every round, no player tx needed ──
    uint256 public constant REVEAL_FEE_MULT = 4;                 // × the round's reveal gas at the current base fee
    uint256 public constant MIN_REVEAL_FEE  = 0.000002 ether;
    mapping(uint256 => uint256) public revealFee;                // bet id → ETH waiting for its pending reveal
    uint256 public expiredRevealEth;                             // fees of rounds nobody revealed → the platform treasury

    // ── Per-player bet ids (uint64 → 4 ids per storage slot) ──
    mapping(address => uint64[]) internal _userBets;

    // ── Staking ──────────────────────────────────────────────
    mapping(address => uint256) public stakerShares;
    mapping(address => uint256) public costBasis;  // tokens put in minus the basis of what was taken out
    uint256 public totalShares;
    uint256 public stakerCount;

    // ── Two-step exits ───────────────────────────────────────
    struct Exit { uint128 shares; uint128 value; uint64 readyBlock; }
    mapping(address => Exit) public exits;   // one pending exit per staker; its shares stay in the pool (and its risk)

    // ── Events (V4 names kept where they exist) ──────────────
    event PoolFunded(address indexed funder, uint256 amount);
    event Staked(address indexed staker, uint256 amount, uint256 shares);
    event Unstaked(address indexed staker, uint256 amount, uint256 shares);
    event PlatformFeeCollected(uint256 amount);
    event CreatorFeeCollected(uint256 amount);
    event ConfigUpdated();
    event Paused(bool paused);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event CreatorUpdated(address oldCreator, address newCreator);
    event EmergencyWithdraw(address indexed owner, uint256 amount);
    event ExpiredSettled(uint256 fromId, uint256 cursor, uint256 closed);
    event UnstakeRequested(address indexed staker, uint256 shares, uint256 value, uint256 readyBlock);
    event UnstakeCancelled(address indexed staker, uint256 shares);
    event Donated(address indexed from, uint256 amount);
    event PayoutOwed(address indexed to, uint256 amount);
    event RevealPaid(uint256 indexed id, address indexed to, uint256 amount);
    event OwedClaimed(address indexed to, uint256 amount);

    modifier onlyOwner() { if (msg.sender != owner) revert NotOwner(); _; }
    modifier whenNotPaused() { if (paused) revert IsPaused(); _; }
    /// a new round: its reveal fee (msg.value) is held for whoever reveals it (the round just created = the last id)
    modifier withRevealFee() { _; _chargeReveal(_betCount() - 1); }
    /// a player's next step of round `id` (hit / stand / climb / guess / draw…) needs a reveal too
    modifier withRevealFeeFor(uint256 id) { _; _chargeReveal(id); }
    /// the caller revealed round `id`: it gets the fee (a player who reveals their own round gets it back)
    modifier paysReveal(uint256 id) { _; _payReveal(id); }

    struct InitArgs {
        address owner; address creator; address token; address factory; address hub;
        string logo; string betName;
        uint256 rtpBP; uint256 feeBP; uint256 maxWinBP; uint256 minBet; uint256 maxBetRatio; uint256 initialPool;
    }

    constructor(InitArgs memory a) {
        if (a.owner == address(0) || a.creator == address(0) || a.token == address(0) || a.hub == address(0)) revert ZeroAddress();
        if (a.initialPool >= MAX_AMOUNT) revert AmountTooLarge();
        owner = a.owner; creator = a.creator;
        factory = a.factory; hub = ICasinoHubV7(a.hub); token = IERC20(a.token);
        tokenLogoUrl = a.logo; betName = a.betName;
        _setConfig(a.rtpBP, a.feeBP, a.maxWinBP, a.minBet, a.maxBetRatio);
        if (a.initialPool > 0) {
            // The factory transfers initialPool right after construction and verifies it arrived.
            poolBalance = uint128(a.initialPool);
            stakerShares[a.owner] = a.initialPool;
            totalShares = a.initialPool;
            costBasis[a.owner] = a.initialPool;
            stakerCount = 1;
            emit Staked(a.owner, a.initialPool, a.initialPool);
        }
    }

    // ── Per-game hooks ───────────────────────────────────────
    /// @dev Number of bet ids issued so far (ids are 0..n-1, in commit order).
    function _betCount() internal view virtual returns (uint256);
    /// @dev Close bet `id` if it can no longer be revealed (stake stays in the pool, reserve
    ///      released). Returns true if the bet is closed (already or now), false if still live.
    function _expireBet(uint256 id, uint256 nowBlock) internal virtual returns (bool closed);
    /// @dev Games whose bets can go live out of id order (blackjack) keep scanning past a live one.
    function _scanPastLive() internal pure virtual returns (bool) { return false; }   // V7: unused — _autoSettle always walks past live bets
    /// @notice Highest config.rtpBP the owner may set. 98%: with 1% platform + 1% creator the
    ///         pool keeps 98% of every stake, so a fair (EV 1.0) game stays LP-neutral at the cap.
    function rtpCap() public pure virtual returns (uint256) { return 9800; }

    // ── Randomness (L2 clock) ────────────────────────────────
    function _l2() internal view returns (uint256) { return ARB.arbBlockNumber(); }

    function _revealHash(uint256 commitBlock) internal view returns (bytes32 h) {
        uint256 eb = commitBlock + REVEAL_DELAY;
        if (_l2() <= eb) revert Wait();
        h = ARB.arbBlockHash(eb);
        if (h == bytes32(0)) revert EntropyExpired();
    }

    function _isExpired(uint256 commitBlock, uint256 nowBlock) internal pure returns (bool) {
        return nowBlock > commitBlock + REVEAL_DELAY + REVEAL_WINDOW;
    }

    function _seed(uint256 commitBlock, address player, uint256 nonce) internal view returns (bytes32) {
        return sha256(abi.encodePacked(_revealHash(commitBlock), player, nonce));
    }

    // ── Betting primitives ───────────────────────────────────
    /// @dev Pull `amount` from the player (exact-amount guard), accrue platform + creator fees,
    ///      put everything else — including the LP fee — into the pool.
    function _pullAndFee(uint256 amount) internal {
        if (amount >= MAX_AMOUNT) revert AmountTooLarge();
        uint256 before = token.balanceOf(address(this));
        token.safeTransferFrom(msg.sender, address(this), amount);
        if (token.balanceOf(address(this)) - before != amount) revert FeeOnTransfer();

        (, uint256 pBP) = hub.feeInfo();
        if (pBP > MAX_PLATFORM_FEE_BP) pBP = MAX_PLATFORM_FEE_BP;
        uint256 pf = (amount * pBP) / BP;
        uint256 cf = (amount * CREATOR_FEE_BP) / BP;
        pendingPlatformFees += uint128(pf);
        pendingCreatorFees += uint128(cf);
        poolBalance += uint128(amount - pf - cf);
        totalVolume += uint128(amount);
    }

    /// @dev Send `amount` without ever reverting the caller: a failed transfer (frozen / blacklisted receiver, a token
    ///      that returns false) is booked as owed and pulled later with claimOwed(). The tokens stay in this contract
    ///      outside the pool.
    function _pay(address to, uint256 amount) internal {
        (bool ok, bytes memory ret) = address(token).call(abi.encodeWithSelector(IERC20.transfer.selector, to, amount));
        if (ok && (ret.length == 0 || abi.decode(ret, (bool))) && address(token).code.length > 0) return;
        owed[to] += amount;
        totalOwed += uint128(amount);
        emit PayoutOwed(to, amount);
    }

    // ── Reveal fees ─────────────────────────────────────────
    /// @notice Gas one reveal of this game typically burns (heavy slot engines override it).
    function revealGas() public pure virtual returns (uint256) { return 200_000; }

    /// @notice ETH a commit must carry: REVEAL_FEE_MULT × revealGas() at the current base fee, at least MIN_REVEAL_FEE.
    ///         Whoever reveals the round gets it — the platform's keeper reveals every round within seconds (a player
    ///         who reveals their own gets it back). Paid in ETH, not the bet token: no price oracle, and the same
    ///         small amount for every bet size. The outcome is fixed by the block hash at commit + REVEAL_DELAY, so WHO
    ///         reveals (or when) can't change it.
    function revealFeeQuote() public view returns (uint256 f) {
        f = revealGas() * block.basefee * REVEAL_FEE_MULT;
        if (f < MIN_REVEAL_FEE) f = MIN_REVEAL_FEE;
    }

    /// @dev every commit carries the fee (one transaction: the bet token + this ETH); it waits for whoever reveals
    function _chargeReveal(uint256 id) internal {
        if (msg.value < revealFeeQuote()) revert RevealFee();
        revealFee[id] += msg.value;
    }

    function _payReveal(uint256 id) internal {
        uint256 f = revealFee[id];
        if (f == 0) return;
        revealFee[id] = 0;
        (bool ok, ) = msg.sender.call{value: f}("");
        if (ok) emit RevealPaid(id, msg.sender, f); else expiredRevealEth += f;
    }

    /// @dev a round closed by expiry: nobody revealed it, its fee goes to the platform
    function _sweepReveal(uint256 id) internal {
        uint256 f = revealFee[id];
        if (f == 0) return;
        revealFee[id] = 0;
        expiredRevealEth += f;
    }

    /// @notice Pull a payout that couldn't be sent when it was due (to `to`, e.g. a fresh wallet of the same owner).
    function claimOwed(address to) external nonReentrant returns (uint256 amount) {
        amount = owed[msg.sender];
        if (amount == 0) revert ZeroAmount();
        if (to == address(0)) revert ZeroAddress();
        owed[msg.sender] = 0;
        totalOwed -= uint128(amount);
        token.safeTransfer(to, amount);
        emit OwedClaimed(msg.sender, amount);
    }

    function availableLiquidity() public view returns (uint256) {
        (uint256 p, uint256 l) = (poolBalance, lockedLiability);
        return p > l ? p - l : 0;
    }

    /// @dev Validate limits against AVAILABLE liquidity and reserve the bet's max payout.
    function _openBet(uint256 amount, uint256 maxPayout) internal {
        Config memory c = config;
        if (amount < c.minBet || amount == 0) revert BelowMinBet();
        if (amount >= MAX_AMOUNT) revert AmountTooLarge();
        uint256 avail = availableLiquidity();
        if (amount > (avail * c.maxBetPoolRatio) / BP) revert BetExceedsMax();
        if (maxPayout > (avail * c.maxWinBP) / BP + amount) revert WinExceedsMax();
        if (maxPayout > avail) revert InsufficientLiquidity();
        lockedLiability += uint128(maxPayout);
    }

    /// @dev Reserve extra liability mid-bet (blackjack double/split).
    function _reserveMore(uint256 add) internal {
        if (add > availableLiquidity()) revert InsufficientLiquidity();
        lockedLiability += uint128(add);
    }

    /// @dev Release the bet's reserve and pay the player (payout ≤ reserve by construction). Never reverts on the
    ///      transfer itself (see _pay): auto-settle closes idle runs through here, so one frozen player can't stop it.
    function _closeBet(address player, uint256 reservedMax, uint256 payout) internal {
        if (payout > reservedMax) revert InsufficientLiquidity();
        lockedLiability -= uint128(reservedMax);
        if (payout > 0) {
            poolBalance -= uint128(payout);
            totalPayouts += uint128(payout);
            _pay(player, payout);
        }
    }

    /// @dev Start of every commit: close a few expired rounds first (frees their reserve for
    ///      this bet) and return the current L2 block (the new bet's commit block).
    function _beginBet() internal returns (uint256 nowBlock) {
        nowBlock = _l2();
        _autoSettle(AUTO_STEPS, nowBlock);
    }

    function _recordBet(address player, uint256 id) internal { _userBets[player].push(uint64(id)); }
    function _userBetAt(address player, uint256 i) internal view returns (uint256) { return _userBets[player][i]; }
    function _userBetCount(address player) internal view returns (uint256) { return _userBets[player].length; }
    /// @notice All bet ids of a player (oldest first).
    function userBetIds(address player) external view returns (uint64[] memory) { return _userBets[player]; }

    /// @dev Close up to `steps` expired rounds. First the closed prefix advances settleCursor; then, past a live bet (a
    ///      run can stand for up to an hour), the walk resumes where the previous one stopped (scanCursor) and wraps
    ///      round the open window — every expired bet behind a standing one is reached, not just the first few.
    ///      Never reverts on a live bet.
    function _autoSettle(uint256 steps, uint256 nowBlock) internal {
        uint256 c = settleCursor;
        uint256 n = _betCount();
        if (c >= n) return;
        uint256 from = c;
        while (c < n && steps != 0 && _expireBet(c, nowBlock)) { _sweepReveal(c); unchecked { ++c; --steps; } }
        if (c != from) settleCursor = uint64(c);
        if (c + 1 >= n) return;                       // nothing open past the first live bet
        uint256 i = scanCursor;
        while (steps != 0) {
            if (i <= c || i >= n) i = c + 1;          // (re)start just past the live bet at the cursor
            if (_expireBet(i, nowBlock)) _sweepReveal(i);
            unchecked { ++i; --steps; }
        }
        scanCursor = uint64(i);
    }

    /// @dev Called by an expiring game right after it closed a round.
    function _countExpired() internal { unchecked { expiredCount += 1; } }

    /// @notice Close up to `maxSteps` rounds whose entropy window has passed. Anyone may call;
    ///         the room also does this by itself on every commit, stake and unstake.
    function settleExpired(uint256 maxSteps) external nonReentrant {
        uint256 from = settleCursor;
        uint256 e0 = expiredCount;
        _autoSettle(maxSteps, _l2());
        emit ExpiredSettled(from, settleCursor, expiredCount - e0);
    }

    /// @notice Open (not yet closed) bets in the cursor window — for UIs and monitoring.
    function openBetWindow() external view returns (uint256 cursor, uint256 total) { return (settleCursor, _betCount()); }

    // ── Staking (fees are in the share price; no claim) ──────
    function _sharesForDeposit(uint256 amount) internal view returns (uint256) {
        return (amount * (totalShares + VIRTUAL)) / (uint256(poolBalance) + VIRTUAL);
    }
    function _assetsForShares(uint256 shares) internal view returns (uint256) {
        return (shares * (uint256(poolBalance) + VIRTUAL)) / (totalShares + VIRTUAL);
    }
    /// @dev What `shares` can take out now: their slice of the pool NET of every open bet's reserved max payout, never
    ///      more than the free liquidity. Pending wins (a standing run's cash-out, an outcome readable before its
    ///      reveal) are inside the reserve, so an exit never leaves before they're paid; the slice of the reserve that
    ///      isn't paid out stays with the LPs who remain.
    function _exitValue(uint256 shares) internal view returns (uint256 v) {
        uint256 avail = availableLiquidity();
        v = (shares * avail) / totalShares;
        if (v > avail) v = avail;
    }

    function stake(uint256 amount) external nonReentrant { _autoSettle(AUTO_STEPS, _l2()); _stake(amount); }
    function fundPool(uint256 amount) external nonReentrant { _autoSettle(AUTO_STEPS, _l2()); _stake(amount); }

    function _stake(uint256 amount) private {
        if (amount == 0) revert ZeroAmount();
        if (amount >= MAX_AMOUNT) revert AmountTooLarge();
        uint256 before = token.balanceOf(address(this));
        token.safeTransferFrom(msg.sender, address(this), amount);
        if (token.balanceOf(address(this)) - before != amount) revert FeeOnTransfer();
        uint256 shares = _sharesForDeposit(amount);
        if (shares == 0) revert TooSmall();
        if (stakerShares[msg.sender] == 0) stakerCount += 1;
        stakerShares[msg.sender] += shares;
        totalShares += shares;
        poolBalance += uint128(amount);
        costBasis[msg.sender] += amount;
        emit Staked(msg.sender, amount, shares);
        emit PoolFunded(msg.sender, amount);
    }

    /// @notice Step 1: fix the value of `shares`. They keep earning and losing until the claim.
    function requestUnstake(uint256 shares) external nonReentrant {
        _autoSettle(UNSTAKE_STEPS, _l2());
        if (exits[msg.sender].shares != 0) revert ExitPending();
        if (shares == 0) revert ZeroAmount();
        if (stakerShares[msg.sender] < shares) revert ExceedsStake();
        uint256 value = _assetsForShares(shares);
        if (value == 0) revert TooSmall();
        uint256 ready = _l2() + EXIT_DELAY;
        exits[msg.sender] = Exit(uint128(shares), uint128(value), uint64(ready));
        emit UnstakeRequested(msg.sender, shares, value, ready);
    }

    /// @notice Step 2 (after EXIT_DELAY L2 blocks): paid the LOWER of the requested value and today's value net of
    ///         open bets (see _exitValue) — claim when few bets are open to get the full value.
    function claimUnstake() external nonReentrant returns (uint256 amount) {
        uint256 nowB = _l2();
        _autoSettle(UNSTAKE_STEPS, nowB);
        Exit memory e = exits[msg.sender];
        if (e.shares == 0) revert NoExit();
        if (nowB < e.readyBlock) revert TooEarly();
        uint256 v = _exitValue(e.shares);
        amount = v < e.value ? v : e.value;
        if (amount == 0) revert LockedByOpenBets();
        delete exits[msg.sender];
        uint256 mine = stakerShares[msg.sender];
        uint256 cb = costBasis[msg.sender];
        costBasis[msg.sender] = cb - (cb * e.shares) / mine;
        stakerShares[msg.sender] = mine - e.shares;
        if (mine == e.shares) stakerCount -= 1;
        totalShares -= e.shares;
        poolBalance -= uint128(amount);             // anything above `amount` stays with the other LPs
        token.safeTransfer(msg.sender, amount);
        emit Unstaked(msg.sender, amount, e.shares);
    }

    /// @notice Drop a pending exit (the shares were never out of the pool).
    function cancelUnstake() external {
        uint256 sh = exits[msg.sender].shares;
        if (sh == 0) revert NoExit();
        delete exits[msg.sender];
        emit UnstakeCancelled(msg.sender, sh);
    }

    /// @notice Add tokens to the pool for every LP (no shares). Needs at least one staker to receive it.
    function donate(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        if (totalShares == 0) revert NoShares();
        uint256 before = token.balanceOf(address(this));
        token.safeTransferFrom(msg.sender, address(this), amount);
        if (token.balanceOf(address(this)) - before != amount) revert FeeOnTransfer();
        if (uint256(poolBalance) + amount >= MAX_AMOUNT) revert AmountTooLarge();
        poolBalance += uint128(amount);
        totalFeesCollected += uint128(amount);
        emit Donated(msg.sender, amount);
    }

    // ── Fee payouts (permissionless triggers, fixed recipients) ──
    /// @notice Send accrued platform fees to the hub's treasury (the ElcasTreasury).
    function flushPlatformFees() public nonReentrant returns (uint256 amount) {
        (address treasury, ) = hub.feeInfo();
        uint256 e = expiredRevealEth;                 // unrevealed rounds' reveal fees (ETH) go along
        if (e > 0) { expiredRevealEth = 0; (bool ok, ) = treasury.call{value: e}(""); if (!ok) expiredRevealEth = e; }
        amount = pendingPlatformFees;
        if (amount == 0) return 0;
        pendingPlatformFees = 0;
        platformFeesSent += uint128(amount);
        token.safeTransfer(treasury, amount);
        emit PlatformFeeCollected(amount);
    }

    /// @notice Send the creator's accrued 1% to the creator. Anyone may trigger it.
    function claimCreatorFees() public nonReentrant returns (uint256 amount) {
        amount = pendingCreatorFees;
        if (amount == 0) return 0;
        pendingCreatorFees = 0;
        creatorFeesSent += uint128(amount);
        _pay(creator, amount);                        // a frozen creator gets it as owed; updateCreator still works
        emit CreatorFeeCollected(amount);
    }

    // ── Owner (the room creator) ─────────────────────────────
    function setPaused(bool p) external onlyOwner { paused = p; emit Paused(p); }

    /// @dev Open bets keep the rtp they were placed with (snapshot).
    function updateConfig(uint256 _rtpBP, uint256 _feeBP, uint256 _maxWinBP, uint256 _minBet, uint256 _maxBetRatio) external onlyOwner {
        _setConfig(_rtpBP, _feeBP, _maxWinBP, _minBet, _maxBetRatio);
        emit ConfigUpdated();
    }

    function _setConfig(uint256 r, uint256 f, uint256 mw, uint256 mb, uint256 mr) internal {
        if (r < MIN_RTP_BP || r > rtpCap() || f > MAX_LP_FEE_BP || mw == 0 || mw > BP || mr == 0 || mr > BP || mb >= MAX_AMOUNT) revert BadConfig();
        config = Config(uint16(r), uint16(f), uint16(mw), uint128(mb), uint16(mr));
    }

    function updateBetName(string calldata n) external onlyOwner { betName = n; }
    function updateTokenLogo(string calldata u) external onlyOwner { tokenLogoUrl = u; }
    function transferOwnership(address n) external onlyOwner { if (n == address(0)) revert ZeroAddress(); emit OwnershipTransferred(owner, n); owner = n; }
    function updateCreator(address c) external {
        if (msg.sender != creator) revert NotCreator();
        if (c == address(0)) revert ZeroAddress();
        if (pendingCreatorFees > 0) claimCreatorFees(); // accrued fees belong to the old creator
        emit CreatorUpdated(creator, c);
        creator = c;
    }

    // ── Views ────────────────────────────────────────────────
    function version() external pure returns (uint256) { return 7; }
    function platformFeeBP() public view returns (uint256 bp) { (, bp) = hub.feeInfo(); if (bp > MAX_PLATFORM_FEE_BP) bp = MAX_PLATFORM_FEE_BP; }
    function platformTreasury() external view returns (address t) { (t, ) = hub.feeInfo(); }
    function totalPlatformFees() public view returns (uint256) { return uint256(platformFeesSent) + pendingPlatformFees; }
    function getPlatformInfo() external view returns (address t, uint256, uint256) { (t, ) = hub.feeInfo(); return (t, totalPlatformFees(), platformFeeBP()); }
    function revealBlocks() external pure returns (uint256) { return REVEAL_DELAY; }
    function revealExtraBlocks() external pure returns (uint256) { return REVEAL_DELAY; }
    /// @dev V4 compat: staker fees are in the share price now, nothing to claim.
    function earned(address) external pure returns (uint256) { return 0; }

    /// @notice V4 shape: (shares, stakeValue, pendingFees = 0, sharePercent bp).
    function getStakerInfo(address s) external view returns (uint256 shares, uint256 stakeValue, uint256 pendingFees, uint256 sharePercent) {
        shares = stakerShares[s];
        if (shares > 0) { stakeValue = _assetsForShares(shares); sharePercent = (shares * BP) / totalShares; }
        pendingFees = 0;
    }

    /// @notice Earn tab: current value, what the staker put in (net of withdrawals) and the
    ///         difference (won/lost, fees included), plus what can be withdrawn right now.
    function stakerPosition(address s) external view returns (uint256 shares, uint256 value, uint256 basis, int256 pnl, uint256 withdrawable) {
        shares = stakerShares[s];
        value = shares > 0 ? _assetsForShares(shares) : 0;
        basis = costBasis[s];
        pnl = int256(value) - int256(basis);
        withdrawable = shares > 0 ? _exitValue(shares) : 0;   // what an exit would pay right now
        if (withdrawable > value) withdrawable = value;
    }

    function getGameInfo() external view returns (
        address, address, string memory, string memory,
        uint256, uint256, uint256, bool, uint256, uint256, uint256, uint256
    ) {
        return (
            owner, address(token), tokenLogoUrl, betName,
            poolBalance, _betCount(), totalVolume, paused,
            totalFeesCollected, totalPayouts, totalShares, stakerCount
        );
    }
}

