// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./CasinoGameBaseV7.sol";

/**
 * @title VideoPokerGameV7 — RABBIT VIDEO POKER (Jacks or Better) on the V7 base
 * @notice Two commit-reveals, like a real machine: `deal` commits the bet and the DEAL block; the
 *         reveal deals 5 cards. The player picks what to hold and `draw` commits the DRAW block; the
 *         reveal replaces the other cards from the 47 not dealt. The replacements come from a block
 *         that doesn't exist yet when the holds are chosen, so nobody can see them first. Holding all
 *         five settles at once (no second draw). BIT-FOR-BIT mirror of the app's pokerEngine.ts.
 *
 * Cards 0…51: rank = c % 13 (0 = 2 … 9 = J, 12 = A), suit = c / 13. Draw j = mod(left) into the cards
 * still in the deck, in card order. Pays (× bet, 9/6 Jacks or Better, Royal 250): Jacks+ 1 · two pair
 * 2 · trips 3 · straight 4 · flush 6 · full house 9 · quads 25 · straight flush 50 · royal 250 — raw
 * return ≈ 98% with best play; the room RTP scales it.
 *
 * `reveal(id)` settles whichever step is pending (keeper-compatible name). Timeouts: a missed reveal
 * loses the hand (the stake stays with the pool); a dealt hand left idle for IDLE_BLOCKS is settled
 * as it stands (all five held) and paid to the player.
 *
 * RNG stream (shared with the other V7 engines): draw i = 64-bit chunk (i % 4) of
 * keccak256(seed ‖ uint32(i / 4)), lowest chunk first.
 */
contract VideoPokerGameV7 is CasinoGameBaseV7 {
    uint256 public constant IDLE_BLOCKS = 36000;            // ≈ 1 h on Robinhood (~10 blocks/s)
    uint256 public constant MAX_PAY = 250;

    enum Status { NONE, DEAL_COMMITTED, DEALT, DRAW_COMMITTED, SETTLED, LOST }
    struct Hand {
        address player; uint48 commitBlock; uint48 lastBlock; uint16 rtpBP; Status status; uint8 hold; uint8 category;
        uint128 amount; uint128 reserved;
        uint128 payout; uint32 dealt; uint32 cards;          // 6 bits per card, card i at bits 6i
    }
    mapping(uint256 => Hand) internal _hands;
    uint256 public totalHands;

    event HandCommitted(uint256 indexed id, address indexed player, uint256 amount);
    event HandDealt(uint256 indexed id, address indexed player, bytes32 seed, uint256 cards);
    event DrawCommitted(uint256 indexed id, address indexed player, uint8 hold);
    event HandSettled(uint256 indexed id, address indexed player, bytes32 seed, uint256 cards, uint8 category, uint256 payout);
    event HandForfeited(uint256 indexed id, address indexed player);

    error WrongState();

    constructor(InitArgs memory a) CasinoGameBaseV7(a) {}

    /// @notice typical gas of one reveal (sets the ETH reveal fee a commit carries — see CasinoGameBaseV7.revealFeeQuote)
    function revealGas() public pure override returns (uint256) { return 300_000; }
    function _betCount() internal view override returns (uint256) { return totalHands; }
    function _scanPastLive() internal pure override returns (bool) { return true; }   // a dealt hand can wait for its holds

    // ── pays + evaluation ────────────────────────────────────
    function payX(uint8 category) public pure returns (uint256) {
        if (category == 1) return 1; if (category == 2) return 2; if (category == 3) return 3; if (category == 4) return 4;
        if (category == 5) return 6; if (category == 6) return 9; if (category == 7) return 25; if (category == 8) return 50;
        if (category == 9) return 250; return 0;
    }

    /// @notice category of 5 cards: 0 nothing · 1 jacks+ · 2 two pair · 3 trips · 4 straight · 5 flush · 6 full house · 7 quads · 8 straight flush · 9 royal
    function evaluate(uint256 packed) public pure returns (uint8) {
        uint256[13] memory cnt;
        uint256 suitMask; uint256 rankMask;
        for (uint256 i = 0; i < 5; ++i) {
            uint256 c = (packed >> (6 * i)) & 63;
            if (c >= 52) revert BadInput();
            cnt[c % 13]++; suitMask |= uint256(1) << (c / 13); rankMask |= uint256(1) << (c % 13);
        }
        bool flush = (suitMask & (suitMask - 1)) == 0;
        bool straight; uint256 high;
        if (_pop(rankMask) == 5) {
            for (uint256 h = 12; h >= 4; --h) { if (((rankMask >> (h - 4)) & 31) == 31) { straight = true; high = h; break; } }
            if (!straight && rankMask == 0x100F) { straight = true; high = 3; }   // A-2-3-4-5
        }
        if (straight && flush) return high == 12 ? 9 : 8;
        uint256 pairs; bool trips; bool quads; bool highPair;
        for (uint256 r = 0; r < 13; ++r) {
            if (cnt[r] == 4) quads = true;
            else if (cnt[r] == 3) trips = true;
            else if (cnt[r] == 2) { pairs++; if (r >= 9) highPair = true; }
        }
        if (quads) return 7;
        if (trips && pairs > 0) return 6;
        if (flush) return 5;
        if (straight) return 4;
        if (trips) return 3;
        if (pairs == 2) return 2;
        if (pairs == 1 && highPair) return 1;
        return 0;
    }
    function _pop(uint256 m) private pure returns (uint256 n) { while (m != 0) { n += m & 1; m >>= 1; } }

    // ── RNG ──────────────────────────────────────────────────
    struct Rng { bytes32 seed; uint256 i; uint256 word; }
    function _mod(Rng memory r, uint256 n) private pure returns (uint256) {
        uint256 i = r.i;
        uint256 k = i & 3;
        uint256 w;
        if (k == 0) {
            bytes32 s = r.seed;
            assembly ("memory-safe") {
                mstore(0x00, s)
                mstore(0x20, shl(224, shr(2, i)))
                w := keccak256(0x00, 0x24)
            }
            r.word = w;
        } else {
            w = r.word;
        }
        unchecked { r.i = i + 1; }
        return ((w >> (64 * k)) & 0xFFFFFFFFFFFFFFFF) % n;
    }
    /// @dev one card from the deck (skipping `used`), marks it used
    function _card(Rng memory r, uint256 used, uint256 left) private pure returns (uint256 c, uint256 usedOut) {
        uint256 x = _mod(r, left);
        for (c = 0; c < 52; ++c) {
            if ((used >> c) & 1 == 1) continue;
            if (x == 0) return (c, used | (uint256(1) << c));
            x--;
        }
        revert BadInput();
    }
    function _deal(bytes32 seed) internal pure returns (uint256 packed) {
        Rng memory r = Rng(seed, 0, 0);
        uint256 used;
        for (uint256 j = 0; j < 5; ++j) { uint256 c; (c, used) = _card(r, used, 52 - j); packed |= c << (6 * j); }
    }
    function _draw(bytes32 seed, uint256 dealt, uint8 hold) internal pure returns (uint256 packed) {
        Rng memory r = Rng(seed, 0, 0);
        uint256 used;
        for (uint256 i = 0; i < 5; ++i) used |= uint256(1) << ((dealt >> (6 * i)) & 63);
        uint256 left = 47;
        for (uint256 i = 0; i < 5; ++i) {
            uint256 c = (dealt >> (6 * i)) & 63;
            if ((hold >> i) & 1 == 0) { (c, used) = _card(r, used, left); left--; }
            packed |= c << (6 * i);
        }
    }

    // ── play ─────────────────────────────────────────────────
    /// @notice Bet and commit the deal (reveal deals the cards).
    function deal(uint256 amount) external payable nonReentrant withRevealFee whenNotPaused returns (uint256 id) {
        if (amount == 0 || amount >= MAX_AMOUNT) revert BadInput();
        uint256 nowB = _beginBet();
        uint16 rtp = config.rtpBP;
        uint256 maxPayout = (amount * MAX_PAY * rtp) / BP;
        _openBet(amount, maxPayout);
        _pullAndFee(amount);
        id = totalHands++;
        Hand storage h = _hands[id];
        h.player = msg.sender; h.commitBlock = uint48(nowB); h.lastBlock = uint48(nowB); h.rtpBP = rtp;
        h.status = Status.DEAL_COMMITTED; h.amount = uint128(amount); h.reserved = uint128(maxPayout);
        _recordBet(msg.sender, id);
        emit HandCommitted(id, msg.sender, amount);
    }

    /// @notice Choose the holds (bit i = keep card i) and commit the draw. Holding all five settles now.
    function draw(uint256 id, uint8 hold) external payable nonReentrant withRevealFeeFor(id) {
        Hand storage h = _hands[id];
        if (h.player != msg.sender) revert NotFound();
        if (h.status != Status.DEALT) revert WrongState();
        if (hold > 31) revert BadInput();
        uint256 nowB = _l2();
        h.hold = hold; h.lastBlock = uint48(nowB);
        if (hold == 31) { _settle(id, h, bytes32(0), h.dealt); return; }
        h.commitBlock = uint48(nowB); h.status = Status.DRAW_COMMITTED;
        emit DrawCommitted(id, msg.sender, hold);
    }

    /// @notice Permissionless: reveal the pending step (the deal, or the draw). Payouts go to the player.
    function reveal(uint256 id) external nonReentrant paysReveal(id) returns (uint256 payout) {
        Hand storage h = _hands[id];
        if (h.player == address(0)) revert NotFound();
        if (h.status == Status.DEAL_COMMITTED) {
            bytes32 seed = _seed(h.commitBlock, h.player, id << 1);
            uint256 cards = _deal(seed);
            h.dealt = uint32(cards); h.cards = uint32(cards); h.status = Status.DEALT; h.lastBlock = uint48(_l2());
            emit HandDealt(id, h.player, seed, cards);
            return 0;
        }
        if (h.status == Status.DRAW_COMMITTED) {
            bytes32 seed = _seed(h.commitBlock, h.player, (id << 1) | 1);
            return _settle(id, h, seed, _draw(seed, h.dealt, h.hold));
        }
        revert AlreadySettled();
    }

    function _settle(uint256 id, Hand storage h, bytes32 seed, uint256 cards) private returns (uint256 payout) {
        uint8 cat = evaluate(cards);
        payout = (uint256(h.amount) * payX(cat) * h.rtpBP) / BP;
        if (payout > h.reserved) payout = h.reserved;       // unreachable by construction
        h.cards = uint32(cards); h.category = cat; h.payout = uint128(payout); h.status = Status.SETTLED;
        _closeBet(h.player, h.reserved, payout);
        emit HandSettled(id, h.player, seed, cards, cat, payout);
    }

    function forfeit(uint256 id) external nonReentrant {
        Hand storage h = _hands[id];
        if (h.player == address(0)) revert NotFound();
        if (h.status == Status.SETTLED || h.status == Status.LOST) revert AlreadySettled();
        if (!_expireBet(id, _l2())) revert TooEarly();
    }

    /// @dev A missed reveal loses the hand; a dealt hand idle too long is settled as it stands (all held).
    function _expireBet(uint256 id, uint256 nowB) internal override returns (bool) {
        Hand storage h = _hands[id];
        Status s = h.status;
        if (s == Status.SETTLED || s == Status.LOST || s == Status.NONE) return true;
        if (s == Status.DEAL_COMMITTED || s == Status.DRAW_COMMITTED) {
            if (!_isExpired(h.commitBlock, nowB)) return false;
            h.status = Status.LOST;
            _closeBet(h.player, h.reserved, 0);
            _countExpired();
            emit HandForfeited(id, h.player);
            return true;
        }
        // DEALT: waiting for holds
        if (nowB <= uint256(h.lastBlock) + IDLE_BLOCKS) return false;
        h.hold = 31;
        _settle(id, h, bytes32(0), h.dealt);
        return true;
    }

    // ── views ────────────────────────────────────────────────
    function previewDeal(bytes32 seed) external pure returns (uint256 cards) { return _deal(seed); }
    function previewDraw(bytes32 seed, uint256 dealt, uint8 hold) external pure returns (uint256 cards) { return _draw(seed, dealt, hold); }

    function hands(uint256 id) external view returns (
        address player, uint8 status, uint256 amount, uint256 reserved, uint256 payout, uint256 rtpBP, uint256 commitBlock,
        uint256 dealt, uint256 cards, uint8 hold, uint8 category, bool settled
    ) {
        Hand storage h = _hands[id];
        return (h.player, uint8(h.status), h.amount, h.reserved, h.payout, h.rtpBP, h.commitBlock, h.dealt, h.cards, h.hold, h.category,
            h.status == Status.SETTLED || h.status == Status.LOST);
    }
    function userHands(address u, uint256 i) external view returns (uint256) { return _userBetAt(u, i); }
    function getUserHandCount(address u) external view returns (uint256) { return _userBetCount(u); }
}
